#include "theron_v1_raw_loader_trace.h"
#include "theron_v1_track02.h"
#include <string.h>
#include <stdio.h>
int theron_v1_raw_loader_trace_ingest(const Theron_V1RawLoaderTraceRow *r,size_t n,size_t bytes,Theron_V1RawLoaderTraceReceipt*out){size_t i;int read=0,pal=0;if(out)memset(out,0,sizeof(*out));if(!r||!out||n<2||!bytes)return 0;for(i=0;i<n;i++){if(i&&r[i].sequence<=r[i-1].sequence)return 0;if(r[i].sector>bytes/THERON_TRACK02_RAW_SECTOR_BYTES||r[i].source_offset>=bytes)return 0;if(r[i].address>=0x1800u&&r[i].address<=0x1803u)read=1;if(read&&r[i].address>=0x0400u&&r[i].address<=0x0403u&&r[i].palette_bank<16u)pal=1;}if(!read||!pal)return 0;out->valid=1;out->palette_descriptor_relation_verified=1;return 1;}
int theron_v1_raw_loader_trace_bind_bitmap_receipt(Theron_V1RawLoaderTraceReceipt *t,const Theron_StartupMediaStateReceipt*m){if(!t||!m||!t->valid||!t->palette_descriptor_relation_verified||!theron_v1_startup_media_state_receipt_has_complete_bitmap_routes(m)||!m->startup_bitmap_raw_route_mask||!m->startup_bitmap_atlas_checksum)return 0;t->bitmap_route_mask=m->startup_bitmap_raw_route_mask;t->bitmap_atlas_checksum=m->startup_bitmap_atlas_checksum;return 1;}
int theron_v1_raw_loader_trace_import_file(const char*p,const char*md5,size_t bytes,Theron_V1RawLoaderTraceReceipt*out){FILE*f;char line[160],id[33];unsigned long sum,want=0;Theron_V1RawLoaderTraceRow rows[64];size_t n=0;uint64_t h=2166136261u;if(out)memset(out,0,sizeof(*out));if(!p||!md5||!out||(f=fopen(p,"r"))==NULL)return 0;if(!fgets(line,sizeof(line),f)||strcmp(line,"THERON_RAW_LOADER_TRACE_V1\n")||!fgets(line,sizeof(line),f)||sscanf(line,"track02_md5=%32s",id)!=1||strcmp(id,md5))goto bad;if(!fgets(line,sizeof(line),f)||sscanf(line,"checksum=%lx",&want)!=1)goto bad;while(fgets(line,sizeof(line),f)){Theron_V1RawLoaderTraceRow*r;if(n>=64||sscanf(line,"%llu %hx %x %zu %hx %hhu",(unsigned long long*)&rows[n].sequence,&rows[n].address,&rows[n].sector,&rows[n].source_offset,&rows[n].destination,&rows[n].palette_bank)!=6)goto bad;r=&rows[n++];h=(h^r->sequence)*16777619u;h=(h^r->address)*16777619u;h=(h^r->sector)*16777619u;h=(h^r->source_offset)*16777619u;}fclose(f);sum=h;if(sum!=want)return 0;return theron_v1_raw_loader_trace_ingest(rows,n,bytes,out);bad:fclose(f);return 0;}
